int waits = 0, total = 0;
for (const Event &e : state.history)
    if (e.kind == "unblocked") {
        ++waits;
        total += e.waited;
    }
if (waits == 0)
    emit("waits: none");
else {
    int average = total * 100 / waits;
    ostringstream line;
    line << "waits: " << waits << " unblocked, total " << total << ", average " << average / 100
         << '.' << setfill('0') << setw(2) << average % 100;
